// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @notice Minimal view of the Binance Agent ID registry on BNB Smart Chain
///         (0x60B9262456dE011F7d15a54CdD8c48bAaa8B022F). `handleOf` returns the
///         caller's Agent ID handle, or an empty string when they hold none.
///         Same registry the BYTE/PROXY/PATCH FairMint engine uses.
interface IAgentIdRegistry {
    function handleOf(address account) external view returns (string memory);
}

/// @notice The slice of OrbitToken the sale needs.
interface IMintableToken {
    function mint(address to, uint256 amount) external;
}

/// @title OrbitSale — a ladder-priced share sale paid in USDT (BEP-20), with referrals.
/// @notice Built on the PATCH FairMint engine (itself adapted from
///         BYTE/PROXY), with the same three PATCH properties:
///           1. Payment is USDT via `transferFrom`, not native BNB.
///           2. The price ladder is keyed to PAID shares sold (`paidSold`),
///              NOT total shares sold, so the 500 free shares never lift the
///              price: the first paid share always costs exactly 1.2 USDT.
///           3. `withdraw` is owner-only and sweeps the whole USDT pot to
///              the treasury.
///
///         ORBIT adds a referral layer on top:
///           - `mint` takes a `referrer`. A referrer is honoured only when
///             it is a different address that holds an Agent ID; anything
///             else (zero address, self, no Agent ID) is silently ignored —
///             it never reverts the purchase.
///           - The first valid referrer a buyer ever presents is recorded
///             once in `invitedBy` and can never be changed.
///           - On the buyer's FIRST paid mint (the first purchase whose cost
///             is greater than zero), a recorded inviter is credited exactly
///             once: +1 bonus quota and +1 invite count. A buyer who only
///             ever claims the free share credits nobody.
///           - The owner can additionally grant off-chain-attested social
///             task quota via `grantTaskQuota`. Effective quota per
///             identity = baseQuota (10) + referral bonus + task quota.
///           - `paidTotal` tracks lifetime USDT paid per wallet, which backs
///             the owner's manual 100%-refund commitment if the sale does
///             not complete.
///
/// Rules of the sale:
///   - Buyers purchase "shares". Each share mints `tokensPerShare` ORBIT
///     directly to the buyer inside the same transaction.
///   - The first share is free for every eligible buyer, while the free
///     pool (`freeCardCap`, 500) lasts. Only one share per purchase can be
///     free.
///   - Paid shares are priced on a ladder over paid shares sold: every
///     `BLOCK_SIZE` (500) paid shares the price steps up by `priceStep`
///     from `basePrice` (1.2 → 1.3 → 1.4 → 1.5 → 1.6 USDT across the 2,500
///     paid shares; a full sellout grosses exactly 3,500 USDT). A purchase
///     that straddles a block boundary prices EACH share at its own
///     block's price.
///   - A per-identity quota caps total shares, free one included, and
///     `maxPerTx` caps a single purchase.
///   - With the Agent ID gate on, only Agent ID holders may buy and quota
///     is tracked per identity (keccak256 of the handle), so moving
///     wallets does not reset it. With the gate off, anyone may buy and
///     quota is tracked per wallet.
///   - `maxCost` protects the buyer if the ladder position moves between
///     quote and execution.
///
/// The sale is the whole story on-chain: a hard cap of 3,000 shares, and
/// when they are gone, minting is over — the token's 220B cap can never
/// be exceeded and no market functions exist in this contract. What
/// happens next is deliberately OFF-contract (the owner's public
/// commitment, exactly like PATCH): after sellout the owner withdraws
/// the USDT pot, sweeps the 70B reserve, and creates the PancakeSwap
/// pool manually (2,800 USDT + the full reserve, LP burned), after which
/// ORBIT simply trades at market price on the DEX.
///
/// The sale has NO transfer tax, NO deadline and NO refund function
/// (`paidTotal` exists so the owner can honour the manual refund
/// commitment if the sale does not complete). Proceeds accumulate in
/// USDT here until the owner calls `withdraw`, which sweeps the entire
/// USDT balance to the treasury.
contract OrbitSale is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ------------------------------------------------------------------
    // Errors
    // ------------------------------------------------------------------
    error ZeroShares();
    error ExceedsTxLimit(uint256 requested, uint256 limit);
    error QuotaExceeded(uint256 requested, uint256 remaining);
    error CostAboveMax(uint256 cost, uint256 maxCost);
    error SaleIsPaused();
    error NoAgentId(address buyer);
    error InvalidConfig();
    error ConfigIsFrozen();
    error NothingToWithdraw();
    error ReserveAlreadyMinted();
    error NothingToSweep();
    error NativeCoinRejected();


    // ------------------------------------------------------------------
    // Events
    // ------------------------------------------------------------------
    event SharesPurchased(
        address indexed buyer,
        bytes32 indexed quotaKey,
        uint256 shares,
        uint256 paidUsdt,
        uint256 freeShares,
        uint256 tokensMinted
    );
    /// @notice Emitted on every mint; the site indexer builds the recent
    ///         mints feed and the Minted ranking from this.
    event Mint(address indexed buyer, uint256 qty, uint256 costUsdt, uint256 freeSharesUsed);
    /// @notice Emitted exactly once per invitee, on their first paid mint;
    ///         the site indexer builds the Invites ranking from this.
    event ReferralCredited(address indexed inviter, address indexed invitee);
    event InviterRecorded(address indexed buyer, address indexed inviter);
    event TaskQuotaGranted(address indexed user, uint256 amount);
    event Withdrawn(address indexed treasury, uint256 amount);
    event ReserveMinted(uint256 amount);
    event ReserveSwept(address indexed treasury, uint256 amount);
    event TreasuryUpdated(address indexed treasury);
    event GateUpdated(bool gateOn);
    event PauseUpdated(bool paused);
    event ConfigFrozen();

    // ------------------------------------------------------------------
    // Constants
    // ------------------------------------------------------------------
    /// @notice Paid shares per ladder block. Fixed at declaration: the
    ///         ladder's shape is part of the sale's promise. With 2,500
    ///         paid shares this yields exactly five blocks.
    uint256 public constant BLOCK_SIZE = 500;

    /// @notice ORBIT minted to this contract by `mintReserve` for the
    ///         post-sellout PancakeSwap pool (70,000,000,000 ORBIT).
    uint256 public constant POOL_RESERVE = 70_000_000_000 ether;

    // ------------------------------------------------------------------
    // Immutable wiring and sale parameters
    // ------------------------------------------------------------------
    IMintableToken public immutable token;
    IAgentIdRegistry public immutable registry;

    /// @notice The payment token: BSC USDT (18 decimals).
    IERC20 public immutable usdt;

    /// @notice Price of a paid share in ladder block 0, in USDT wei.
    ///         A compile-time constant rather than a constructor parameter
    ///         (same pattern as PROXY's hardcoded `sharesPerTier`): the
    ///         ladder's numbers are part of the sale's promise and can
    ///         never be reshaped, not even by the owner. Together with
    ///         `priceStep` and `BLOCK_SIZE` this hardcodes the full
    ///         schedule: 1.2 / 1.3 / 1.4 / 1.5 / 1.6 USDT.
    uint256 public constant basePrice = 1.2 ether;

    /// @notice Amount added to the price per ladder block, in USDT wei.
    uint256 public constant priceStep = 0.1 ether;

    /// @notice Tokens minted per share, in wei (18 decimals).
    uint256 public immutable tokensPerShare;

    /// @notice Total shares that will ever be sold (free + paid).
    uint256 public immutable totalCards;

    /// @notice How many of those shares are handed out free (one per buyer).
    uint256 public immutable freeCardCap;

    /// @notice Maximum shares per identity (or per wallet when ungated),
    ///         before referral/task bonus quota is added.
    uint256 public immutable baseQuota;

    /// @notice Maximum shares in a single purchase.
    uint256 public immutable maxPerTx;

    // ------------------------------------------------------------------
    // Mutable configuration
    // ------------------------------------------------------------------
    /// @notice Where sale proceeds go when `withdraw` is called.
    address public treasury;

    /// @notice When true, only Agent ID holders can buy and quota follows
    ///         the identity. When false, quota follows the wallet.
    bool public gateOn;

    bool public paused;
    bool public frozen;

    // ------------------------------------------------------------------
    // Sale progress
    // ------------------------------------------------------------------
    uint256 public cardsSold;
    uint256 public paidSold;
    uint256 public freeGiven;

    /// @notice Lifetime USDT accepted by the sale (before withdrawals).
    uint256 public collected;

    /// @notice True once the pool reserve has been minted.
    bool public reserveMinted;

    /// @notice Shares taken, keyed by identity (gated) or wallet (ungated).
    mapping(bytes32 => uint256) public quotaUsed;

    /// @notice True once an address has consumed its free share.
    mapping(address => bool) public freeClaimed;

    /// @notice Lifetime USDT paid per wallet. Backs the owner's manual
    ///         refund commitment if the sale does not complete.
    mapping(address => uint256) public paidTotal;

    // ------------------------------------------------------------------
    // Referral and bonus quota (keyed like `quotaUsed`: per identity)
    // ------------------------------------------------------------------
    /// @notice The inviter recorded for a buyer: the first valid referrer
    ///         they ever presented. Zero while none has been recorded.
    mapping(address => address) public invitedBy;

    /// @notice Quota key of the recorded inviter, captured at recording
    ///         time so the credit lands on the inviter's identity even if
    ///         they later buy from a different wallet.
    mapping(address => bytes32) internal _invitedByKey;

    /// @notice True once a buyer's inviter has been credited for them.
    mapping(address => bool) public referralCredited;

    /// @notice Referral bonus quota earned, per identity key.
    mapping(bytes32 => uint256) internal _bonusQuota;

    /// @notice Social-task quota granted by the owner, per identity key.
    mapping(bytes32 => uint256) internal _taskQuota;

    /// @notice Successful invites credited, per identity key.
    mapping(bytes32 => uint256) internal _inviteCount;

    // ------------------------------------------------------------------
    // Deployment
    // ------------------------------------------------------------------
    constructor(
        address token_,
        address registry_,
        address usdt_,
        address treasury_,
        uint256 tokensPerShare_,
        uint256 totalCards_,
        uint256 freeCardCap_,
        uint256 baseQuota_,
        uint256 maxPerTx_,
        bool gateOn_,
        address initialOwner_
    ) Ownable(initialOwner_) {
        if (
            !_configValid(
                token_, registry_, usdt_, treasury_, tokensPerShare_, totalCards_, freeCardCap_, baseQuota_, maxPerTx_, gateOn_, initialOwner_
            )
        ) {
            revert InvalidConfig();
        }

        token = IMintableToken(token_);
        registry = IAgentIdRegistry(registry_);
        usdt = IERC20(usdt_);
        treasury = treasury_;
        tokensPerShare = tokensPerShare_;
        totalCards = totalCards_;
        freeCardCap = freeCardCap_;
        baseQuota = baseQuota_;
        maxPerTx = maxPerTx_;
        gateOn = gateOn_;
    }

    /// @dev Constructor argument validation, kept in its own frame: with
    ///      this many constructor parameters the checks would otherwise push
    ///      the constructor past the stack limit (same pattern as PROXY).
    function _configValid(
        address token_,
        address registry_,
        address usdt_,
        address treasury_,
        uint256 tokensPerShare_,
        uint256 totalCards_,
        uint256 freeCardCap_,
        uint256 baseQuota_,
        uint256 maxPerTx_,
        bool gateOn_,
        address initialOwner_
    ) internal pure returns (bool) {
        return token_ != address(0) && usdt_ != address(0) && treasury_ != address(0)
            && initialOwner_ != address(0) && (!gateOn_ || registry_ != address(0)) && tokensPerShare_ != 0
            && totalCards_ != 0 && baseQuota_ != 0 && maxPerTx_ != 0 && maxPerTx_ <= baseQuota_
            && freeCardCap_ <= totalCards_;
    }

    // ------------------------------------------------------------------
    // Ladder pricing
    // ------------------------------------------------------------------
    /// @notice Price of one paid share in ladder block `blockIndex`, USDT wei.
    function priceAtBlock(uint256 blockIndex) public pure returns (uint256) {
        return basePrice + blockIndex * priceStep;
    }

    /// @notice Ladder block the NEXT paid share falls in.
    function currentBlock() public view returns (uint256) {
        return paidSold / BLOCK_SIZE;
    }

    /// @notice Price of the next paid share, in USDT wei.
    function currentPrice() public view returns (uint256) {
        return priceAtBlock(currentBlock());
    }

    /// @notice Total USDT cost of `count` paid shares starting at the
    ///         current `paidSold`. Each share is priced at its own block:
    ///         a run that crosses a block boundary pays the old price for
    ///         the shares before the boundary and the new price after it.
    function _ladderCost(uint256 count) internal view returns (uint256 total) {
        uint256 remaining = count;
        uint256 pos = paidSold;
        while (remaining > 0) {
            uint256 blockIndex = pos / BLOCK_SIZE;
            uint256 roomInBlock = BLOCK_SIZE - (pos % BLOCK_SIZE);
            uint256 take = remaining < roomInBlock ? remaining : roomInBlock;
            total += take * priceAtBlock(blockIndex);
            pos += take;
            remaining -= take;
        }
    }

    // ------------------------------------------------------------------
    // Buying
    // ------------------------------------------------------------------
    /// @notice Buy `shares` shares, paying in USDT (approve this contract
    ///         first). The first share is free while the free pool lasts.
    /// @param shares   How many shares to buy in this transaction.
    /// @param maxCost  The most USDT (wei) the buyer accepts being charged.
    ///                 The call reverts if the actual cost is higher, which
    ///                 guards against the ladder moving between quote and
    ///                 execution.
    /// @param referrer Optional inviter. Honoured only if it is a different
    ///                 address holding an Agent ID; otherwise ignored. The
    ///                 first valid referrer is recorded permanently, and the
    ///                 inviter is credited (+1 bonus quota, +1 invite) on
    ///                 this buyer's first paid purchase.
    /// @return charged   USDT actually kept by the sale (wei).
    /// @return tokensOut Tokens minted to the buyer (wei).
    function mint(uint256 shares, uint256 maxCost, address referrer)
        external
        nonReentrant
        returns (uint256 charged, uint256 tokensOut)
    {
        if (paused) revert SaleIsPaused();
        if (shares == 0) revert ZeroShares();
        if (shares > maxPerTx) revert ExceedsTxLimit(shares, maxPerTx);

        bytes32 key = _quotaKey(msg.sender);

        // Record the inviter before anything else: the first valid
        // referrer this buyer ever presents sticks forever.
        _recordInviter(referrer);

        // At most one share per purchase is free: the buyer's first, and
        // only while the free pool still has room.
        uint256 freeShares = (!freeClaimed[msg.sender] && freeGiven < freeCardCap) ? 1 : 0;

        // One quota check over the whole purchase, against the effective
        // quota (base + referral bonus + task grants). Checking
        // share-by-share would let buyers sidestep the limit with repeated
        // small buys.
        uint256 quota = _effectiveQuota(key);
        uint256 used = quotaUsed[key];
        if (used + shares > quota) revert QuotaExceeded(shares, quota - used);
        if (cardsSold + shares > totalCards) revert QuotaExceeded(shares, totalCards - cardsSold);

        uint256 paidShares = shares - freeShares;
        charged = _ladderCost(paidShares);
        if (charged > maxCost) revert CostAboveMax(charged, maxCost);

        // Referral credit: exactly once per invitee, on their first paid
        // purchase — the helper checks that this purchase costs something
        // and that the buyer has never paid before (`paidTotal` is still
        // zero at this point).
        _creditReferralIfDue(charged);

        // Effects first, external calls last.
        cardsSold += shares;
        paidSold += paidShares;
        quotaUsed[key] += shares;
        if (freeShares == 1) {
            freeGiven += 1;
            freeClaimed[msg.sender] = true;
        }
        collected += charged;
        paidTotal[msg.sender] += charged;
        tokensOut = shares * tokensPerShare;

        // Pull the payment, then mint the tokens straight to the buyer.
        if (charged > 0) {
            usdt.safeTransferFrom(msg.sender, address(this), charged);
        }
        token.mint(msg.sender, tokensOut);

        emit SharesPurchased(msg.sender, key, shares, charged, freeShares, tokensOut);
        emit Mint(msg.sender, shares, charged, freeShares);
    }

    /// @dev Record `referrer` as the buyer's inviter if none is recorded
    ///      yet and the referrer is valid: not zero, not the buyer, and
    ///      holding an Agent ID. Anything invalid is ignored by design —
    ///      a bad referrer must never block a purchase.
    function _recordInviter(address referrer) internal {
        if (invitedBy[msg.sender] != address(0)) return;
        if (referrer == address(0) || referrer == msg.sender) return;
        if (address(registry) == address(0)) return;
        string memory handle = registry.handleOf(referrer);
        if (bytes(handle).length == 0) return;
        invitedBy[msg.sender] = referrer;
        _invitedByKey[msg.sender] = keccak256(bytes(handle));
        emit InviterRecorded(msg.sender, referrer);
    }

    /// @dev Credit the caller's recorded inviter (+1 bonus quota, +1
    ///      invite count) if this purchase is the caller's first paid one.
    ///      MUST be called before `paidTotal` for this purchase is added:
    ///      a still-zero `paidTotal` is what marks the purchase as the
    ///      first. Fires at most once per buyer, ever.
    function _creditReferralIfDue(uint256 charged) internal {
        if (charged == 0 || paidTotal[msg.sender] != 0 || referralCredited[msg.sender]) return;
        address inviter = invitedBy[msg.sender];
        if (inviter == address(0)) return;
        referralCredited[msg.sender] = true;
        bytes32 inviterKey = _invitedByKey[msg.sender];
        _bonusQuota[inviterKey] += 1;
        _inviteCount[inviterKey] += 1;
        emit ReferralCredited(inviter, msg.sender);
    }

    // ------------------------------------------------------------------
    // Identity and quota
    // ------------------------------------------------------------------
    /// @dev Quota key for a buyer. Enforces the Agent ID gate as a side effect.
    function _quotaKey(address buyer) internal view returns (bytes32) {
        if (!gateOn) return _walletKey(buyer);
        string memory handle = registry.handleOf(buyer);
        if (bytes(handle).length == 0) revert NoAgentId(buyer);
        return keccak256(bytes(handle));
    }

    function _walletKey(address buyer) internal pure returns (bytes32) {
        return bytes32(uint256(uint160(buyer)));
    }

    /// @notice The key a wallet's quota is tracked under. With the gate on this
    ///         is keccak256(handle); a wallet without an Agent ID maps to
    ///         keccak256 of the empty string and cannot buy anyway.
    function quotaKeyOf(address who) public view returns (bytes32) {
        if (!gateOn) return _walletKey(who);
        return keccak256(bytes(registry.handleOf(who)));
    }

    /// @dev Effective quota for an identity key: base + referral + tasks.
    function _effectiveQuota(bytes32 key) internal view returns (uint256) {
        return baseQuota + _bonusQuota[key] + _taskQuota[key];
    }

    /// @notice Total shares `who` may take: base quota plus earned bonus
    ///         quota (referrals) and granted task quota.
    function effectiveQuota(address who) external view returns (uint256) {
        return _effectiveQuota(quotaKeyOf(who));
    }

    /// @notice Shares `who` has taken so far (free + paid).
    function mintedBy(address who) external view returns (uint256) {
        return quotaUsed[quotaKeyOf(who)];
    }

    /// @notice Referral bonus quota `who` has earned as an inviter.
    function bonusQuota(address who) external view returns (uint256) {
        return _bonusQuota[quotaKeyOf(who)];
    }

    /// @notice Social-task quota granted to `who` by the owner.
    function taskQuota(address who) external view returns (uint256) {
        return _taskQuota[quotaKeyOf(who)];
    }

    /// @notice Buyers `who` has successfully invited (credited invites).
    function inviteCount(address who) external view returns (uint256) {
        return _inviteCount[quotaKeyOf(who)];
    }

    // ------------------------------------------------------------------
    // Quotes and views
    // ------------------------------------------------------------------
    /// @notice What `who` would pay for `shares` shares right now, in
    ///         USDT wei. Mirrors the free-share rule used by `mint`.
    function quote(address who, uint256 shares) public view returns (uint256) {
        if (shares == 0) return 0;
        uint256 freeShares = (!freeClaimed[who] && freeGiven < freeCardCap) ? 1 : 0;
        return _ladderCost(shares - freeShares);
    }

    /// @notice `quote` for the caller, convenient for agents and front-ends.
    function quoteForCaller(uint256 shares) external view returns (uint256) {
        return quote(msg.sender, shares);
    }

    function cardsRemaining() external view returns (uint256) {
        return totalCards - cardsSold;
    }

    function freeCardsRemaining() external view returns (uint256) {
        return freeCardCap - freeGiven;
    }

    /// @notice Shares `who` can still take under their effective quota.
    function quotaLeft(address who) external view returns (uint256) {
        bytes32 key = quotaKeyOf(who);
        uint256 used = quotaUsed[key];
        uint256 quota = _effectiveQuota(key);
        return used >= quota ? 0 : quota - used;
    }

    // ------------------------------------------------------------------
    // Owner quota grants (social tasks, attested off-chain)
    // ------------------------------------------------------------------
    /// @notice Grant `amount` extra quota to `user` for completed social
    ///         tasks. Attestation happens off-chain; this only records the
    ///         result. Grants stack with referral bonus quota and never
    ///         expire. There is deliberately no revoke: a grant is a
    ///         public, permanent record (see TaskQuotaGranted).
    function grantTaskQuota(address user, uint256 amount) external onlyOwner {
        _taskQuota[quotaKeyOf(user)] += amount;
        emit TaskQuotaGranted(user, amount);
    }

    // ------------------------------------------------------------------
    // Proceeds
    // ------------------------------------------------------------------
    /// @notice Forward the sale's entire USDT balance to the treasury.
    ///         Owner-only (a deliberate PATCH change from BYTE/PROXY, where
    ///         anyone could trigger the sweep).
    function withdraw() external onlyOwner {
        uint256 balance = usdt.balanceOf(address(this));
        if (balance == 0) revert NothingToWithdraw();
        usdt.safeTransfer(treasury, balance);
        emit Withdrawn(treasury, balance);
    }

    // ------------------------------------------------------------------
    // Pool reserve
    // ------------------------------------------------------------------
    /// @notice Mint the one-time pool reserve (70B ORBIT) to this contract.
    ///         Callable exactly once, by the owner, after `setMinter` has
    ///         wired this sale as the token's minter. The reserve then sits
    ///         here until `sweepReserve` moves it for the pool launch.
    function mintReserve() external onlyOwner {
        if (reserveMinted) revert ReserveAlreadyMinted();
        reserveMinted = true;
        token.mint(address(this), POOL_RESERVE);
        emit ReserveMinted(POOL_RESERVE);
    }

    /// @notice Move this contract's entire ORBIT balance to the treasury.
    ///         After sellout this is how the owner takes the 70B reserve
    ///         out to build the PancakeSwap pool manually (off-contract,
    ///         his public commitment — the sale itself never touches a
    ///         pool).
    function sweepReserve() external onlyOwner {
        IERC20 orbit = IERC20(address(token));
        uint256 balance = orbit.balanceOf(address(this));
        if (balance == 0) revert NothingToSweep();
        orbit.safeTransfer(treasury, balance);
        emit ReserveSwept(treasury, balance);
    }

    // ------------------------------------------------------------------
    // Owner controls
    // ------------------------------------------------------------------
    function setTreasury(address newTreasury) external onlyOwner {
        _requireNotFrozen();
        if (newTreasury == address(0)) revert InvalidConfig();
        treasury = newTreasury;
        emit TreasuryUpdated(newTreasury);
    }

    function setGate(bool on) external onlyOwner {
        _requireNotFrozen();
        gateOn = on;
        emit GateUpdated(on);
    }

    /// @notice Pause or resume buying. Deliberately NOT blocked by `freeze`:
    ///         the owner keeps an emergency stop even after locking config.
    function setPaused(bool shouldPause) external onlyOwner {
        paused = shouldPause;
        emit PauseUpdated(shouldPause);
    }

    /// @notice Permanently lock treasury and gate. Pause still works.
    function freeze() external onlyOwner {
        frozen = true;
        emit ConfigFrozen();
    }

    /// @dev Renouncing also freezes first, so an ownerless sale is immutable.
    function renounceOwnership() public override onlyOwner {
        frozen = true;
        super.renounceOwnership();
    }

    function _requireNotFrozen() internal view {
        if (frozen) revert ConfigIsFrozen();
    }

    /// @dev Bare native-coin transfers are rejected: funds only enter
    ///      through `mint`, as USDT, where shares are accounted for.
    receive() external payable {
        revert NativeCoinRejected();
    }
}
